const listCancelRequested = `-- name: ListCancelRequested :many
SELECT id FROM investigations
WHERE id = ANY($1::uuid[]) AND cancel_requested_at IS NOT NULL
`

// ListCancelRequested returns which of the investigations with ids have a
// stop asked for.
func (q *Queries) ListCancelRequested(ctx context.Context, ids []uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listCancelRequested, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

